long key_read_value(key_serial_t keyid, char __user *buffer, size_t buflen) {
    struct key *key;
    long ret = 0;

    key = keyring_lookup(keyid);
    if (!key || key->flags & KEY_FLAG_NEGATIVE) {
        return -ENOENT;
    }

    if (current_uid() != key->uid && !has_perm(current_task(), key, KEY_NEED_VIEW)) {
        return -EACCES;
    }

    down_read(&key->sem);
    if (key->payload.data != NULL && buflen >= key->payload.data_len) {
        ret = copy_to_user(buffer, key->payload.data, key->payload.data_len);
        if (ret == 0) {
            ret = key->payload.data_len;
        } else {
            ret = -EFAULT;
        }
    } else {
        ret = -EINVAL;
    }
    up_read(&key->sem);

    return ret;
}

