    if (IS_ERR(key)) {
        return PTR_ERR(key);
    }

    if (key->flags & 1) {
        key_put(key);
        return -ENOKEY;
    }

    if (!ptrace_may_access(current, key, 1)) {
        key_put(key);
        return -EACCES;
